// ---------------------------------------------------------------------------
// AUTO-GENERATED by Claude Code
// Purpose: the one box of the Alt+I inline chat, wherever it shows: the robot, the input, the
//          status text (its look: assets/app.css; a widget's bar draws the same markup,
//          render.strip_ask_box).
//          Used under a code editor (inline_edit.jsx) and in a framed pane's title strip
//          (assets/frame_ask.js, the Terminal's). Where the box sits is the user's (app.css
//          `.cm-panels .inline-box`, `.strip-ask .inline-box`).
// Usage: const box = inlineBox({ placeholder, hint }); parent.append(box.dom);
//        box.say("Thinking…"); box.thinking(true); box.say("failed", "error");
// ---------------------------------------------------------------------------

// Its look is in assets/app.css ("the inline AI box"): every box is in the app's page, which has it.

const el = (tag, className, text) => {
  const node = document.createElement(tag);
  node.className = className;
  if (text) node.textContent = text;
  return node;
};

/** A box, not yet in the page: { dom, input, status, say(text, kind), thinking(on) }.
 *  hint: the status text it starts with. kind: "" (grey), "note" or "error". */
export function inlineBox({ placeholder, hint }) {
  const dom = el("div", "inline-box");
  const input = el("input", "inline-box-input");
  input.placeholder = placeholder;
  input.spellcheck = false;
  input.autocomplete = "off";
  const status = el("span", "inline-box-status", hint);
  dom.append(el("span", "inline-box-icon ai-icon", ""), input, status);
  return {
    dom,
    input,
    status,
    say(text, kind) {
      status.textContent = text;
      status.className = `inline-box-status${kind ? ` is-${kind}` : ""}`;
    },
    thinking(on) {
      dom.classList.toggle("is-thinking", on);
    },
  };
}
